{"content":"import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<void> _initialLoadFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _isLoadingMore = false;
  bool _hasMore = true;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _refreshFresh();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadPage(int page, {bool append = false}) async {
    final settingsRepository = context.read<SettingsRepository>();
    final currencyRepository = context.read<CurrencyRepository>();
    final String baseCurrency = settingsRepository.baseCurrency;

    final CurrencyPageRequest request = CurrencyPageRequest(base: baseCurrency, page: page, pageSize: 20);
    final CurrencyPage result = await currencyRepository.fetchRates(request);

    if (!mounted) return;

    if (append) {
      _allCurrencies.addAll(result.items);
    } else {
      _allCurrencies = List<CurrencyModel>.from(result.items);
      _currentPage = 0;
      _filteredCurrenciesNotifier.value = List<CurrencyModel>.from(_allCurrencies);
    }

    _hasMore = result.hasMore;
    _isLoadingMore = false;

    if (!append) {
      currencyRepository.saveCurrencyList(_allCurrencies);
      _fadeController.forward();
    }
  }

  void _initData() {
    _filteredCurrenciesNotifier = ValueNotifier([]);
    _initialLoadFuture = _loadPage(0).catchError((Object error) {
      if (mounted) {
        setState(() {});
      }
    });
  }

  Future<void> _refreshFresh() async {
    if (!mounted) return;

    setState(() {
      _currentPage = 0;
      _isLoadingMore = false;
      _hasMore = true;
      _allCurrencies = [];
    });

    await _loadPage(0).catchError((Object error) {
      if (mounted) {
        setState(() {});
      }
    });
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

