import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/app/currency_list/widgets/currency_card.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

Widget buildTestWidget({required Widget child, required MockCurrencyRepository mockCurrencyRepo, required MockSettingsRepository mockSettingsRepo}) => MultiProvider(
      providers: [
        Provider<CurrencyRepository>.value(value: mockCurrencyRepo),
        Provider<SettingsRepository>.value(value: mockSettingsRepo),
      ],
      child: MaterialApp(
        localizationsDelegates: AppLocalizations.localizationsDelegates,
        supportedLocales: AppLocalizations.supportedLocales,
        home: child,
      ),
    );

Future<void> _waitForLoaded(WidgetTester tester) async {
  // pump() — запускает FutureBuilder и начинает асинхронную загрузку
  await tester.pump();
  // pumpAndSettle() ждёт завершения всех pending futures и анимаций.
  // Используем с таймаутом чтобы избежать бесконечного ожидания
  try {
    await tester.pumpAndSettle(const Duration(seconds: 5));
  } catch (_) {}
}

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('CurrencyListPage', () {
    late MockCurrencyRepository mockCurrencyRepository;
    late MockSettingsRepository mockSettingsRepository;

    final currencyItems = [
      CurrencyModel(
        id: '1',
        nominal: 1,
        name: 'Доллар США',
        symbol: 'USD',
        value: 78.4181,
        previousValue: 78.5,
      ),
      CurrencyModel(
        id: '2',
        nominal: 1,
        name: 'Евро',
        symbol: 'EUR',
        value: 92.7440,
        previousValue: 92.2,
      ),
    ];

    setUp(() {
      mockCurrencyRepository = MockCurrencyRepository();
      mockSettingsRepository = MockSettingsRepository();
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
      when(mockSettingsRepository.baseCurrency).thenReturn('EUR');
    });

    testWidgets('should display all currency items when loaded', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildTestWidget(child: CurrencyListPage(), mockCurrencyRepo: mockCurrencyRepository, mockSettingsRepo: mockSettingsRepository),
      );

      // показан загрузчик
      expect(find.byType(CircularProgressIndicator), findsOneWidget);

      await _waitForLoaded(tester);

      expect(find.text('USD'), findsOneWidget);
      expect(find.text('EUR'), findsOneWidget);
      expect(find.text('JPY'), findsNothing);
      expect(find.byType(CurrencyCard), findsNWidgets(currencyItems.length));
    });

    testWidgets('should navigate to detail page when currency card is tapped', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildTestWidget(child: const CurrencyListPage(), mockCurrencyRepo: mockCurrencyRepository, mockSettingsRepo: mockSettingsRepository),
      );

      await _waitForLoaded(tester);

      await tester.tap(find.byType(CurrencyCard).first);
      await tester.pump(const Duration(milliseconds: 300));

      expect(find.byType(CurrencyDetailPage), findsOneWidget);
    });

    testWidgets('should filter currencies when search text is entered', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildTestWidget(child: const CurrencyListPage(), mockCurrencyRepo: mockCurrencyRepository, mockSettingsRepo: mockSettingsRepository),
      );

      await _waitForLoaded(tester);

      await tester.enterText(find.byType(TextField), 'Евро');
      await tester.pump();

      expect(find.byType(CurrencyCard), findsOneWidget);
    });

    testWidgets('should hide showMore button when no more pages', (WidgetTester tester) async {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));

      await tester.pumpWidget(
        buildTestWidget(child: const CurrencyListPage(), mockCurrencyRepo: mockCurrencyRepository, mockSettingsRepo: mockSettingsRepository),
      );

      await _waitForLoaded(tester);

      expect(find.text('Показать ещё'), findsNothing);
    });
  });
}
