import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _isLoadingMore = false;
  bool _hasMore = true;
  bool _isLoaded = false;

  // Кэшируем репозитории для использования в асинхронных колбэках
  late CurrencyRepository _currencyRepository;
  late SettingsRepository _settingsRepository;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    // Получаем репозитории синхронно до начала асинхронных операций
    _currencyRepository = context.read<CurrencyRepository>();
    _settingsRepository = context.read<SettingsRepository>();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && mounted) {
      _refreshFresh();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadPage(int page, {bool append = false}) async {
    final String baseCurrency = _settingsRepository.baseCurrency;

    final CurrencyPageRequest request = CurrencyPageRequest(base: baseCurrency, page: page, pageSize: 20);
    final CurrencyPage result = await _currencyRepository.fetchRates(request);

    if (!mounted) return;

    if (append) {
      _allCurrencies.addAll(result.items);
    } else {
      _allCurrencies = List<CurrencyModel>.from(result.items);
      _currentPage = 0;
      _filteredCurrenciesNotifier.value = List<CurrencyModel>.from(_allCurrencies);
    }

    setState(() {
      _hasMore = result.hasMore;
      _isLoadingMore = false;
      if (!append) {
        _isLoaded = true;
      }
    });

    if (!append) {
      _currencyRepository.saveCurrencyList(_allCurrencies);
      _fadeController.forward();
    }
  }

  void _initData() {
    _filteredCurrenciesNotifier = ValueNotifier([]);
    _loadPage(0).catchError((Object error) {});
  }

  Future<void> _refreshFresh() async {
    if (!mounted) return;

    setState(() {
      _currentPage = 0;
      _isLoadingMore = false;
      _hasMore = true;
      _allCurrencies = [];
      _isLoaded = false;
    });

    await _loadPage(0).catchError((Object error) {});
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  Future<void> _loadMore() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() {
      _isLoadingMore = true;
    });

    final nextPage = _currentPage + 1;
    await _loadPage(nextPage, append: true).catchError((Object error) {});
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: !_isLoaded
          ? const Center(child: CircularProgressIndicator())
          : FadeTransition(
              opacity: _fadeController.view,
              child: Column(
                children: [
                  Padding(
                    padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                    child: SearchView(onChanged: _filterCurrencies),
                  ),
                  Expanded(
                    child: ValueListenableBuilder<List<CurrencyModel>>(
                      valueListenable: _filteredCurrenciesNotifier,
                      builder: (BuildContext context, List<CurrencyModel> data, _) {
                        final int itemCount = _hasMore ? data.length + 1 : data.length;

                        return ListView.builder(
                          itemCount: itemCount,
                          itemBuilder: (BuildContext context, int index) {
                            if (index >= data.length) {
                              // Показываем индикатор загрузки при "Показать ещё"
                              return const Center(
                                child: Padding(
                                  padding: EdgeInsets.all(16.0),
                                  child: CircularProgressIndicator(),
                                ),
                              );
                            }

                            final CurrencyModel currency = data[index];

                            return Padding(
                              key: ValueKey(currency.id),
                              padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                              child: CurrencyCard(model: currency),
                            );
                          },
                          padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                        );
                      },
                    ),
                  ),
                  if (_hasMore)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 16.0),
                      child: ElevatedButton(
                        onPressed: _isLoadingMore ? null : _loadMore,
                        child: _isLoadingMore
                            ? const SizedBox(
                                height: 20,
                                width: 20,
                                child: CircularProgressIndicator(strokeWidth: 2),
                              )
                            : Text(context.loc.showMore),
                      ),
                    ),
                ],
              ),
            ),
    );
  }
}

